code.cpp:
class Solution {
public:
    int longestSubstring(string s, int k) {
        int n = s.size();
        int ans = 0;
        for (int target = 1; target <= 26; target++) {
            int cnt[26] = {0};
            int unique = 0;
            int atLeastK = 0;
            int left = 0;
            for (int right = 0; right < n; right++) {
                int idx = s[right] - 'a';
                if (cnt[idx] == 0) unique++;
                cnt[idx]++;
                if (cnt[idx] == k) atLeastK++;

                while (unique > target) {
                    int lidx = s[left] - 'a';
                    if (cnt[lidx] == k) atLeastK--;
                    cnt[lidx]--;
                    if (cnt[lidx] == 0) unique--;
                    left++;
                }

                if (unique == target && atLeastK == target) {
                    ans = max(ans, right - left + 1);
                }
            }
        }
        return ans;
    }
};
